13	public sealed record PeticionRegistrada(string Metodo, string Url, IReadOnlyDictionary<string, string> Cabeceras, string Cuerpo)
14	{
15	    public JsonNode Json => JsonNode.Parse(Cuerpo)!;
16	    public string? Cabecera(string nombre) => Cabeceras.TryGetValue(nombre, out var v) ? v : null;
17	}
