58	public sealed class LogsEnMemoria : ILoggerProvider
59	{
60	    private readonly List<string> _lineas = [];
61	    public string Todo { get { lock (_lineas) return string.Join("\n", _lineas); } }
62	
63	    public ILogger CreateLogger(string categoria) => new Registro(this, categoria);
64	    public void Dispose() { }
65	
66	    private void Agregar(string s) { lock (_lineas) _lineas.Add(s); }
67	
68	    private sealed class Registro(LogsEnMemoria dueno, string categoria) : ILogger
69	    {
70	        public IDisposable? BeginScope<TState>(TState state) where TState : notnull => null;
71	        public bool IsEnabled(LogLevel logLevel) => true;
72	        public void Log<TState>(LogLevel nivel, EventId id, TState state, Exception? ex, Func<TState, Exception?, string> f)
73	        {
74	            var sb = new StringBuilder().Append(categoria).Append(' ').Append(f(state, ex));
75	            if (state is IEnumerable<KeyValuePair<string, object?>> kv)
76	                foreach (var p in kv) sb.Append(' ').Append(p.Key).Append('=').Append(p.Value);
77	            if (ex != null) sb.Append(' ').Append(ex);
78	            dueno.Agregar(sb.ToString());
79	        }
80	    }
81	}
