23	    var proveedor = (cfg["LLM_PROVIDER"] ?? "").Trim();
24	    if (proveedor.Length == 0 || proveedor.Equals("openai", StringComparison.OrdinalIgnoreCase))
25	        return ActivatorUtilities.CreateInstance<OpenAiCompatClient>(sp);
26	    if (proveedor.Equals("anthropic", StringComparison.OrdinalIgnoreCase))
