41	app.MapPost("/api/asistente/preguntar", async (HttpRequest req, Datos datos, IConfiguration cfg, Asistente asistente) =>
42	{
43	    static IResult Error(int codigo, string msg) => Results.Json(new { error = msg }, statusCode: codigo);
44	
45	    JsonDocument doc;
46	    try { doc = await JsonDocument.ParseAsync(req.Body); }
47	    catch (JsonException) { return Error(400, "El cuerpo no es un JSON válido."); }
48	
49	    using (doc)
50	    {
51	        var raiz = doc.RootElement;
52	        if (raiz.ValueKind != JsonValueKind.Object) return Error(400, "El cuerpo debe ser un objeto JSON.");
53	
54	        if (!raiz.TryGetProperty("pregunta", out var p) || p.ValueKind != JsonValueKind.String
55	            || string.IsNullOrWhiteSpace(p.GetString()))
56	            return Error(400, "La pregunta es obligatoria.");
57	        if (p.GetString()!.Length > 1000) return Error(400, "La pregunta no puede superar 1.000 caracteres.");
58	
59	        if (!raiz.TryGetProperty("usuario", out var u) || u.ValueKind != JsonValueKind.Object)
60	            return Error(400, "El usuario es obligatorio.");
61	        if (!u.TryGetProperty("rol", out var r) || r.ValueKind != JsonValueKind.String)
62	            return Error(400, "El rol es obligatorio.");
63	        var rol = r.GetString()!;
64	        if (rol != "estudiante" && rol != "coordinador")
65	            return Error(400, "El rol debe ser 'estudiante' o 'coordinador'.");
66	        if (!u.TryGetProperty("id", out var i) || i.ValueKind != JsonValueKind.String
67	            || string.IsNullOrWhiteSpace(i.GetString()))
68	            return Error(400, "El id del usuario es obligatorio.");
69	
70	        var usuario = Permisos.ResolverUsuario(datos, rol, i.GetString()!);
71	        if (usuario == null) return Error(403, "Usuario no válido.");
72	        if (Permisos.MencionaTercero(datos, usuario, p.GetString()!))
73	            return Error(403, "No tienes permiso para consultar datos de otros estudiantes.");
74	
75	        if (string.IsNullOrWhiteSpace(cfg["LLM_API_KEY"]))
76	            return Error(503, "El servicio del modelo no está disponible: falta configurar LLM_API_KEY.");
77	
78	        AsistenteResultado res;
79	        try { res = await asistente.ResponderAsync(usuario, p.GetString()!, req.HttpContext.RequestAborted); }
80	        catch (OperationCanceledException) when (req.HttpContext.RequestAborted.IsCancellationRequested) { throw; }
81	        catch (Exception) { return Error(503, "El proveedor del modelo no está disponible."); }
82	
83	        if (res.PermisoDenegado) return Error(403, "No tienes permiso para consultar esos datos.");
84	
85	        // T5 reemplaza este 0 por el cálculo con el precio configurado.
86	        const double costoUsd = 0;
