19	
20	    private static string Texto(string prov, string texto, int entrada, int salida, int cacheCrea = 0, int cacheLee = 0) =>
21	        prov == "openai"
22	            ? new JsonObject
23	            {
24	                ["choices"] = new JsonArray(new JsonObject { ["message"] = new JsonObject { ["role"] = "assistant", ["content"] = texto }, ["finish_reason"] = "stop" }),
25	                ["usage"] = new JsonObject { ["prompt_tokens"] = entrada, ["completion_tokens"] = salida, ["total_tokens"] = entrada + salida },
26	            }.ToJsonString()
27	            : new JsonObject
28	            {
29	                ["id"] = "msg_1", ["type"] = "message", ["role"] = "assistant", ["stop_reason"] = "end_turn",
30	                ["content"] = new JsonArray(new JsonObject { ["type"] = "text", ["text"] = texto }),
31	                ["usage"] = UsoAnthropic(entrada, salida, cacheCrea, cacheLee),
32	            }.ToJsonString();
33	
34	    private static JsonObject UsoAnthropic(int entrada, int salida, int cacheCrea, int cacheLee) => new()
35	    {
36	        ["input_tokens"] = entrada, ["output_tokens"] = salida,
37	        ["cache_creation_input_tokens"] = cacheCrea, ["cache_read_input_tokens"] = cacheLee,
38	    };
39	
40	    private static string Herramientas(string prov, int entrada, int salida, int cacheCrea, int cacheLee,
41	        params (string Id, string Nombre, string Args)[] llamadas) =>
42	        prov == "openai"
43	            ? new JsonObject
44	            {
45	                ["choices"] = new JsonArray(new JsonObject
46	                {
47	                    ["message"] = new JsonObject
48	                    {
49	                        ["role"] = "assistant", ["content"] = null,
50	                        ["tool_calls"] = new JsonArray(llamadas.Select(l => (JsonNode)new JsonObject
51	                        {
52	                            ["id"] = l.Id, ["type"] = "function",
53	                            ["function"] = new JsonObject { ["name"] = l.Nombre, ["arguments"] = l.Args },
54	                        }).ToArray()),
55	                    },
56	                    ["finish_reason"] = "tool_calls",
57	                }),
58	                ["usage"] = new JsonObject { ["prompt_tokens"] = entrada, ["completion_tokens"] = salida },
59	            }.ToJsonString()
60	            : new JsonObject
61	            {
62	                ["id"] = "msg_t", ["type"] = "message", ["role"] = "assistant", ["stop_reason"] = "tool_use",
63	                ["content"] = new JsonArray(llamadas.Select(l => (JsonNode)new JsonObject
64	                {
65	                    ["type"] = "tool_use", ["id"] = l.Id, ["name"] = l.Nombre, ["input"] = JsonNode.Parse(l.Args),
66	                }).ToArray()),
67	                ["usage"] = UsoAnthropic(entrada, salida, cacheCrea, cacheLee),
68	            }.ToJsonString();
